 public Compositor(Context c,ATSModel m,MediaFiles files){context=c;model=m;media=files;}
 public Typeface font(String name){Typeface f=fonts.get(name);if(f!=null)return f;String file=name.startsWith("Inter")?"inter.ttf":name.equals("Poppins")?"Poppins-Black.ttf":name.equals("Luckiest Guy")?"LuckiestGuy.ttf":name.equals("Bebas Neue")?"BebasNeue.ttf":name.equals("Playfair Display")?"playfairdisplay.ttf":name.equals("Noto Nastaliq Urdu")?"notonastaliqurdu.ttf":name.equals("DejaVu Sans")?"DejaVuSans.ttf":name.equals("Liberation Sans")?"LiberationSans-Bold.ttf":name.equals("Source Code Pro")?"SourceCodePro-Regular.ttf":name.equals("Inconsolata")?"Inconsolata-Regular.ttf":name.equals("Bitstream Vera Sans")?"VeraIt.ttf":name.equals("Oswald")?"oswald.ttf":name+".ttf";try{f=Typeface.createFromAsset(context.getAssets(),"fonts/"+file);}catch(Exception e){f=Typeface.create(name.equals("Consolas")?"monospace":name.equals("Georgia")?"serif":"sans-serif",Typeface.BOLD);}int weight=name.equals("Montserrat")||name.equals("Poppins")||name.equals("Inter Black")?900:name.equals("Inter Bold")?700:name.equals("Inter Medium")?500:400;if(android.os.Build.VERSION.SDK_INT>=28)f=Typeface.create(f,weight,false);else if(weight>=700)f=Typeface.create(f,Typeface.BOLD);fonts.put(name,f);return f;}
 private void buffers(int w,int h){if(current!=null&&w==width&&h==height)return;if(current!=null){current.recycle();previous.recycle();}width=w;height=h;current=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);previous=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);}
 public synchronized void render(Bitmap output,int frame)throws Exception{buffers(output.getWidth(),output.getHeight());frame=Math.max(0,Math.min(model.totalFrames-1,frame));int index=model.sceneAt(frame);ATSModel.Scene scene=model.scenes.get(index);drawScene(new Canvas(current),scene,frame);Canvas c=new Canvas(output);c.drawColor(Color.BLACK);if(index>0&&scene.transitionFrames>0&&frame-scene.first<scene.transitionFrames){ATSModel.Scene prior=model.scenes.get(index-1);drawScene(new Canvas(previous),prior,prior.last-1);transition(c,scene,(frame-scene.first+1f)/scene.transitionFrames,frame);}else c.drawBitmap(current,0,0,null);moments(c,scene,frame);overlays(c,scene,frame);captions(c,frame/(double)model.fps);if(model.ending.optString("mode","HOLD").equals("FADE_OUT")){int n=model.ending.optInt("frames",12);if(n>0&&frame>=model.totalFrames-n){paint.setColor(Color.BLACK);paint.setAlpha(Math.min(255,(int)(255*(frame-model.totalFrames+n+1f)/n)));c.drawRect(0,0,width,height,paint);paint.setAlpha(255);}}}
 public RectF crop(ATSModel.Scene s,Bitmap image,int frame){float iw=image.getWidth(),ih=image.getHeight(),ratio=width/(float)height;double p=Math.max(0,Math.min(1,(frame-s.first)/(double)Math.max(1,s.last-s.first-1)));p=ease(p,s.config.optString("ease","EASE_IN_OUT"));float z0=1,z1=1;switch(s.motion){case "SLOW_PUSH_IN":case "KEN_BURNS":case "GENTLE_DIAGONAL":z0=1.04f;z1=1.16f;break;case "SLOW_ZOOM_OUT":z0=1.16f;z1=1.04f;break;case "TINY_PUNCH_IN":z0=1;z1=1.09f;p=Math.min(1,p*5);break;case "PAN_UP":case "PAN_DOWN":case "PAN_LEFT":case "PAN_RIGHT":z0=z1=1.12f;}
  float z=(float)(s.config.optDouble("zoom_from",z0)*(1-p)+s.config.optDouble("zoom_to",z1)*p);float cw=Math.min(iw,ih*ratio)/z,ch=cw/ratio;JSONObject focus=ATSModel.obj(s.config,"focus");float fx=(float)focus.optDouble("x",.5),fy=(float)focus.optDouble("y",.5);if(s.motion.equals("PAN_LEFT"))fx=(float)(.58-.16*p);if(s.motion.equals("PAN_RIGHT"))fx=(float)(.42+.16*p);if(s.motion.equals("PAN_UP"))fy=(float)(.58-.16*p);if(s.motion.equals("PAN_DOWN"))fy=(float)(.42+.16*p);if(s.motion.equals("KEN_BURNS")||s.motion.equals("GENTLE_DIAGONAL")){fx+=(float)((p-.5)*.08);fy+=(float)((p-.5)*.05);}float left=Math.max(0,Math.min(iw-cw,iw*fx-cw/2)),top=Math.max(0,Math.min(ih-ch,ih*fy-ch/2));return new RectF(left,top,left+cw,top+ch);}
 private Matrix mapping(ATSModel.Scene s,Bitmap img,int frame){Matrix m=new Matrix();RectF source=fit?new RectF(0,0,img.getWidth(),img.getHeight()):crop(s,img,frame);m.setRectToRect(source,new RectF(0,0,width,height),fit?Matrix.ScaleToFit.CENTER:Matrix.ScaleToFit.FILL);if(fit&&!s.motion.equals("STATIC")){double p=ease(Math.max(0,Math.min(1,(frame-s.first)/(double)Math.max(1,s.last-s.first-1))),s.config.optString("ease","EASE_IN_OUT"));float scale=(float)(s.motion.equals("SLOW_ZOOM_OUT")?1-.12*p:.88+.12*p);m.postScale(scale,scale,width*.5f,height*.5f);float remaining=1-scale,dx=0,dy=0;if(s.motion.equals("PAN_LEFT")||s.motion.equals("PAN_RIGHT"))dx=(float)((p-.5)*width*remaining*(s.motion.equals("PAN_LEFT")?-1:1));if(s.motion.equals("PAN_UP")||s.motion.equals("PAN_DOWN"))dy=(float)((p-.5)*height*remaining*(s.motion.equals("PAN_UP")?-1:1));m.postTranslate(dx,dy);}return m;}
 private JSONObject look(String name){JSONObject o=looks.get(name);if(o!=null)return o;try(java.io.InputStream in=context.getAssets().open("looks/"+name+".json")){byte[]b=new byte[8192];int n=in.read(b);o=new JSONObject(new String(b,0,n,"UTF-8"));}catch(Exception e){o=new JSONObject();}looks.put(name,o);return o;}
 private void drawScene(Canvas c,ATSModel.Scene s,int frame)throws Exception{c.drawColor(Color.BLACK);Bitmap img=media.image(s.id,Math.max(width,height));JSONObject lo=ATSModel.obj(s.raw,"look_override");JSONObject profile=PresetCatalog.style(model.style.optString("preset","LEGACY"));String name=lo.optString("look",model.style.optString("look",profile.optString("look","CLEAN")));JSONObject l=look(name);float intensity=(float)lo.optDouble("intensity",model.style.optDouble("look_intensity",profile.optDouble("look_intensity",1)));float saturation=1-(float)l.optDouble("monochrome",0)*intensity,warm=(float)l.optDouble("warm",0)*intensity;JSONObject fin=ATSModel.obj(model.direction,"finish");float contrast=1+(float)fin.optDouble("contrast",0)*.3f;ColorMatrix cm=new ColorMatrix();cm.setSaturation(saturation);cm.postConcat(new ColorMatrix(new float[]{contrast,0,0,0,128*(1-contrast)+warm*25,0,contrast,0,0,128*(1-contrast),0,0,contrast,0,128*(1-contrast)-warm*25,0,0,0,1,0}));paint.reset();paint.setFilterBitmap(true);paint.setAntiAlias(true);paint.setColorFilter(new ColorMatrixColorFilter(cm));int radius=(int)(Math.max(s.config.optDouble("blur",0),l.optDouble("soften",0)*intensity*.3)*Math.min(img.getWidth(),img.getHeight())*.02);Bitmap source=img;if(radius>0){String key=s.id+":"+img.getWidth()+":"+radius;if(!blurKey.equals(key)){if(blurred!=null)blurred.recycle();blurred=Blur.apply(img,radius);blurKey=key;}source=blurred;}c.drawBitmap(source,mapping(s,img,frame),paint);paint.setColorFilter(null);float vig=(float)fin.optDouble("vignette",l.optDouble("vignette",0)*intensity);if(vig>0){paint.setShader(new RadialGradient(width*.5f,height*.48f,(float)Math.hypot(width,height)*.6f,new int[]{0,Color.argb((int)(vig*200),0,0,0)},new float[]{.30f,1},Shader.TileMode.CLAMP));c.drawRect(0,0,width,height,paint);paint.setShader(null);}float grain=(float)fin.optDouble("grain",l.optDouble("grain",0)*intensity);if(grain>0){if(noise==null)noise=Bitmap.createBitmap(128,128,Bitmap.Config.ARGB_8888);Random r=new Random(model.seed+frame);int[]pixels=new int[16384];for(int i=0;i<pixels.length;i++){int v=r.nextInt(256);pixels[i]=Color.argb((int)(grain*45),v,v,v);}noise.setPixels(pixels,0,128,0,0,128,128);paint.setShader(new BitmapShader(noise,Shader.TileMode.REPEAT,Shader.TileMode.REPEAT));c.drawRect(0,0,width,height,paint);paint.setShader(null);}}
